// Non-secret settings for ff-search-triage (PDF task 5, weekly part).
//   n8n credentials: FF Supabase (service role), FF OpenAI.
// Daily 07:30 (after the 06:00 sync) for the last 7 days, and from the dashboard
// ("Sort new searches"). Webhook body (optional): { client_id, days: 7..30 }
const SETTINGS = {
  SUPABASE_URL: 'https://SET-ME.supabase.co',
  SUPABASE_ANON_KEY: 'SET-ME',
  ALLOWED_ROLES: ['rob_admin', 'ff_staff'],
  USE_AI: true, // false: only the FF blocked words and names are used; the rest goes to Rob
};

const src = $input.first().json || {};
const fromWebhook = Boolean(src.headers);
const body = fromWebhook && src.body && typeof src.body === 'object' ? src.body : {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const days = Number.isInteger(body.days) && body.days >= 1 && body.days <= 30 ? body.days : 7;

return [{
  json: {
    ...SETTINGS,
    body,
    trigger: fromWebhook ? 'manual' : 'schedule',
    only_client_id: typeof body.client_id === 'string' && uuid.test(body.client_id) ? body.client_id : null,
    days,
  },
}];

// Auth check block 1/4 - read the bearer token. Never log it.
const headers = $('Webhook').first().json.headers || {};
const raw = headers.authorization || headers.Authorization || '';
const match = /^Bearer\s+(\S+)$/i.exec(String(raw).trim());
return [{ json: { token: match ? match[1] : '' } }];

// Auth check block 4/4 - decide. Output: { ok, status, error?, user? }
const cfg = $('Config').first().json;
const token = $('Auth: read token').first().json.token;
const userRes = $('Auth: verify token').first().json;
const profileRes = $('Auth: load profile').first().json;

const deny = (status, error) => [{ json: { ok: false, status, error } }];

if (!token) return deny(401, 'Missing login token.');
if (userRes.statusCode !== 200 || !userRes.body || !userRes.body.id) {
  return deny(401, 'Login token is not valid or has expired.');
}
if (profileRes.statusCode !== 200) return deny(500, 'Could not load the login profile.');

const rows = Array.isArray(profileRes.body) ? profileRes.body : [];
const profile = rows[0];
if (!profile || profile.user_id !== userRes.body.id) return deny(403, 'This login has no access.');
if (profile.disabled) return deny(403, 'This login has been turned off.');
if (!cfg.ALLOWED_ROLES.includes(profile.role)) {
  return deny(403, 'Your role does not allow this action.');
}

return [{
  json: {
    ok: true,
    status: 200,
    user: {
      user_id: profile.user_id,
      email: profile.email,
      role: profile.role,
      client_id: profile.client_id,
    },
  },
}];

// First pass, no AI: a search term that contains an FF blocked word (same
// matching as Google negatives: exact / phrase / all words), a competitor's name
// or the client's own name is "block" - obvious junk (Robin: "block obvious junk
// yourself"). Everything else goes to the AI in one batch per campaign.
// Output: one item { rule_rows, ai_batches } (counts only in logs, never terms).
const cfg = $('Config').first().json;
const campaigns = $('Get candidates').all().map((i) => i.json).filter((c) => c && c.customer_id && Array.isArray(c.terms));
const universal = $('Get blocked words').all().map((i) => i.json).filter((r) => r && r.text);

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 '&.-]+/g, ' ').replace(/\s+/g, ' ').trim();
function matches(term, neg, type) {
  const t = norm(term);
  const n = norm(neg);
  if (!n) return false;
  if (type === 'EXACT') return t === n;
  if (type === 'PHRASE') return ` ${t} `.includes(` ${n} `);
  const words = new Set(t.split(' '));
  return n.split(' ').every((w) => words.has(w));
}

const now = new Date().toISOString();
const ruleRows = [];
const aiBatches = [];
for (const c of campaigns) {
  const rest = [];
  for (const term of c.terms) {
    let theme = null;
    let why = null;
    const u = universal.find((x) => matches(term.term, x.text, x.match_type));
    if (u) { theme = u.theme; why = `FF blocked word "${u.text}"`; }
    if (!theme) {
      const comp = (c.competitor_terms || []).find((x) => matches(term.term, x, 'PHRASE'));
      if (comp) { theme = 'competitor'; why = 'competitor name'; }
    }
    if (!theme) {
      const own = ((c.own_brand_terms || []).length ? c.own_brand_terms : [c.client_name]).find((x) => matches(term.term, x, 'PHRASE'));
      if (own) { theme = 'own name'; why = "the client's own name"; }
    }
    if (theme) {
      ruleRows.push({
        customer_id: c.customer_id, campaign_id: c.campaign_id, term_hash: term.term_hash, search_term: term.term,
        decision: 'block', theme, note: `Sorted automatically: ${why}.`, decided_by: null, decided_how: 'rule', decided_at: now,
      });
    } else {
      rest.push(term);
    }
  }
  if (rest.length && cfg.USE_AI) {
    aiBatches.push({
      customer_id: c.customer_id, campaign_id: c.campaign_id, campaign_name: c.campaign_name || '', client_name: c.client_name || '',
      process: c.process === 'online_cremation' ? 'an online cremation provider' : 'a funeral home',
      towns: (c.towns || []).join(', ') || 'not set', terms: rest,
      list: rest.map((t, i) => `${i + 1}. ${t.term} (clicks ${t.clicks}, conversions ${Math.round(Number(t.conversions || 0) * 10) / 10})`).join('\n'),
    });
  } else if (rest.length) {
    for (const t of rest) {
      ruleRows.push({
        customer_id: c.customer_id, campaign_id: c.campaign_id, term_hash: t.term_hash, search_term: t.term,
        decision: 'ask_rob', theme: null, note: 'Not sorted automatically (AI is off).', decided_by: null, decided_how: 'rule', decided_at: now,
      });
    }
  }
}

return [{ json: { rule_rows: ruleRows, ai_batches: aiBatches, campaigns: campaigns.length } }];

